import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiStrengthen","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/strengthen/index.md","filePath":"en/modules/strengthen/index.md","lastUpdated":0}`),a={name:`en/modules/strengthen/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakistrengthen" tabindex="-1">EmakiStrengthen <a class="header-anchor" href="#emakistrengthen" aria-label="Permalink to “EmakiStrengthen”">​</a></h1><p>EmakiStrengthen provides star-based equipment strengthening, temper state, protection materials, branch trees, attribute output, strengthen layer rebuilding, and a public API.</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>Some commands still use the historical <code>crack</code> naming (such as <code>clearcrack</code>); gameplay documentation refers to it consistently as &quot;temper&quot;.</p></div><h2 id="module-facts" tabindex="-1">Module facts <a class="header-anchor" href="#module-facts" aria-label="Permalink to “Module facts”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module version</td><td><code>4.8.0</code></td></tr><tr><td>Main command</td><td><code>/emakistrengthen</code></td></tr><tr><td>Alias</td><td><code>/estrengthen</code></td></tr><tr><td>Hard dependency</td><td>EmakiCoreLib</td></tr><tr><td>Soft dependency</td><td>EmakiItem, EmakiAttribute, PlaceholderAPI</td></tr><tr><td>Main permissions</td><td><code>emakistrengthen.use</code>, <code>emakistrengthen.reload</code>, <code>emakistrengthen.debug</code>, <code>emakistrengthen.admin</code></td></tr></tbody></table><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to “Pages”">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./commands.html">Commands</a></td><td>Opening the strengthen GUI, inspecting the held item, refreshing display, setting stars, and giving materials.</td></tr><tr><td><a href="./recipes.html">Recipes</a></td><td>Success rates, material costs, failure penalties, effects, and actions in <code>recipes/*.yml</code>.</td></tr><tr><td><a href="./process.html">Process</a></td><td>The full strengthen flow from recipe matching to PDC writes and display refresh.</td></tr><tr><td><a href="./branch.html">Branch Trees</a></td><td>Strengthen routes per star range and the attributes, skills, and display each route grants.</td></tr><tr><td><a href="./broadcast.html">Broadcast</a></td><td>Notifying nearby or all players the first time a star tier is reached.</td></tr><tr><td><a href="./placeholders.html">Placeholders</a></td><td>PlaceholderAPI output.</td></tr><tr><td><a href="./corelib-actions.html">CoreLib Actions</a></td><td>Rebuilding and modifying the main-hand strengthen layer.</td></tr><tr><td><a href="./api.html">API</a></td><td>Reading state, previewing, and executing strengthening through <code>EmakiStrengthenApi</code>.</td></tr><tr><td><a href="./events.html">Event API</a></td><td>Bukkit events and interception points across the strengthen flow.</td></tr></tbody></table><h2 id="core-concepts" tabindex="-1">Core concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to “Core concepts”">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>Description</th></tr></thead><tbody><tr><td>Strengthen star</td><td>Current strengthen tier of the item, such as +1, +2, or +10.</td></tr><tr><td>Strengthen recipe</td><td>Defines which items can be strengthened, required materials, success rate, and results.</td></tr><tr><td>Material plan</td><td>Checks and consumes strengthen materials, protection materials, and temper materials.</td></tr><tr><td>Temper</td><td>A level accumulated on failure that raises later success rates by <code>temper_chance_bonus_per_level</code>.</td></tr><tr><td>Failure downgrade</td><td>When the target star is 6 or higher and no protection material is used, failure drops one star.</td></tr><tr><td>Protection material</td><td>A material with <code>protection: true</code> that prevents a star drop on failure.</td></tr><tr><td>Branch tree</td><td>Forks into different strengthen routes after a configured star.</td></tr><tr><td>Strengthen layer</td><td>Writes to the item&#39;s strengthen namespace layer and is rebuilt by CoreLib.</td></tr></tbody></table><h2 id="default-runtime-folder" tabindex="-1">Default runtime folder <a class="header-anchor" href="#default-runtime-folder" aria-label="Permalink to “Default runtime folder”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiStrengthen/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── recipes/</span></span>
<span class="line"><span>│   ├── example_recipe.yml</span></span>
<span class="line"><span>│   └── example_branch_recipe.yml</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>│   └── strengthen_gui.yml</span></span>
<span class="line"><span>└── lang/</span></span>
<span class="line"><span>    ├── zh_CN.yml</span></span>
<span class="line"><span>    └── en_US.yml</span></span></code></pre></div><p><code>recipes/</code> defines the strengthen rules for different items; <code>gui/strengthen_gui.yml</code> defines the layout of the strengthen interface.</p><h2 id="main-config-yml" tabindex="-1">Main <code>config.yml</code> <a class="header-anchor" href="#main-config-yml" aria-label="Permalink to “Main config.yml”">​</a></h2><p>See <a href="./process.html">Process</a> for <code>success_rates</code> and <a href="./broadcast.html">Broadcast</a> for <code>local_broadcast_radius</code> and <code>broadcast.*</code>. The remaining fields are:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>version</code></td><td>string</td><td><code>4.8.0</code></td><td>Configuration-structure marker; the shipped resource version is maintained by the resource sync flow. Two distinct internal constants exist: a blank key falls back to <code>4.5.9</code>, and with no config file at all <code>AppConfig.defaults()</code> uses <code>4.2.9</code>. Neither is a release coordinate.</td></tr><tr><td><code>language</code></td><td>string</td><td><code>zh_CN</code></td><td>Uses <code>lang/&lt;language&gt;.yml</code>.</td></tr><tr><td><code>release_default_data</code></td><td>boolean</td><td><code>true</code></td><td>Releases the bundled default recipes, GUI, and language resources when missing.</td></tr><tr><td><code>affix.max_level</code></td><td>integer</td><td><code>10</code></td><td>Maximum level per affix; negative values are treated as <code>0</code>.</td></tr><tr><td><code>affix.capacity_max</code></td><td>integer</td><td><code>100</code></td><td>Affix capacity ceiling; negative values are treated as <code>0</code>.</td></tr><tr><td><code>affix.capacity_cost_per_level</code></td><td>integer</td><td><code>10</code></td><td>Capacity consumed per affix level; negative values are treated as <code>0</code>.</td></tr><tr><td><code>affix.bonus_per_level</code></td><td>double</td><td><code>1.0</code></td><td>Bonus granted per affix level; non-finite values are treated as <code>0</code>.</td></tr><tr><td><code>enhancement.reject_container_target</code></td><td>boolean</td><td><code>false</code></td><td>Rejects container items as the enhancement target.</td></tr><tr><td><code>enhancement.reject_container_material</code></td><td>boolean</td><td><code>false</code></td><td>Rejects container items as enhancement material.</td></tr><tr><td><code>enhancement.min_success_rate</code></td><td>double</td><td><code>0.0</code></td><td>Lower bound on success rate after all reductions are applied.</td></tr><tr><td><code>enhancement.diminishing_returns.per_level</code></td><td>double</td><td><code>0.0</code></td><td>Success rate lost per level once <code>start_level</code> is reached.</td></tr><tr><td><code>enhancement.diminishing_returns.start_level</code></td><td>integer</td><td><code>1</code></td><td>First level at which diminishing returns apply.</td></tr><tr><td><code>enhancement.cost_growth.per_level</code></td><td>double</td><td><code>0.0</code></td><td>Cost growth factor per level.</td></tr><tr><td><code>enhancement.cost_growth.max_multiplier</code></td><td>double</td><td><code>0.0</code></td><td>Upper bound on the cost growth multiplier.</td></tr><tr><td><code>enhancement.failure_demotion.levels</code></td><td>integer</td><td><code>0</code></td><td>Levels lost on failure.</td></tr><tr><td><code>enhancement.failure_demotion.floor_level</code></td><td>integer</td><td><code>0</code></td><td>Failure demotion never drops below this level.</td></tr><tr><td><code>enhancement.pity_retry.interval_ticks</code></td><td>integer</td><td><code>0</code></td><td>Retry interval in ticks after a pity-counter persistence failure.</td></tr><tr><td><code>enhancement.pity_retry.max_attempts</code></td><td>integer</td><td><code>0</code></td><td>Maximum pity-counter persistence retries.</td></tr><tr><td><code>enhancement.mastery.exp_per_attempt</code></td><td>double</td><td><code>0.0</code></td><td>Mastery experience granted per attempt.</td></tr><tr><td><code>enhancement.mastery.exp_per_success</code></td><td>double</td><td><code>0.0</code></td><td>Additional mastery experience granted per success.</td></tr><tr><td><code>enhancement.mastery.soft_cap</code></td><td>integer</td><td><code>0</code></td><td>Mastery soft cap.</td></tr></tbody></table><h2 id="typical-strengthen-flow" tabindex="-1">Typical strengthen flow <a class="header-anchor" href="#typical-strengthen-flow" aria-label="Permalink to “Typical strengthen flow”">​</a></h2><ol><li>Open the strengthen GUI with <code>/estrengthen open</code>.</li><li>Insert target equipment, strengthen materials, and optional protection materials.</li><li>Match an available recipe through the recipe&#39;s top-level <code>matcher</code> and <code>slot_groups</code> fields.</li><li>Check conditions, materials, economy costs, and the current star limit.</li><li>Calculate the success rate: target-star base rate plus temper bonus, clamped to <code>success_chance_cap</code>.</li><li>Fire <code>StrengthenPreAttemptEvent</code>, allowing external code to adjust the rate or cancel.</li><li>Roll the outcome and charge materials and costs.</li><li>On success, raise the star by one, write the strengthen layer, and run that star&#39;s <code>actions.success</code>.</li><li>On failure, accumulate temper and possibly drop a star, then run <code>actions.failure</code>.</li><li>CoreLib rebuilds the item presentation; reaching a broadcast star for the first time sends a local or global broadcast.</li></ol><h2 id="relation-with-attribute" tabindex="-1">Relation with Attribute <a class="header-anchor" href="#relation-with-attribute" aria-label="Permalink to “Relation with Attribute”">​</a></h2><p>Strengthen can run as a display-and-progression system only. With <code>ea_attribute</code> effects configured and EmakiAttribute installed, each star can contribute real stats: attributes are written through the EmakiAttribute authoritative API into a structured PDC layer and participate in real combat calculation.</p><p>When EmakiAttribute is absent, Strengthen takes a no-op path: strengthening still completes but no attributes are written.</p><h2 id="relation-with-item" tabindex="-1">Relation with Item <a class="header-anchor" href="#relation-with-item" aria-label="Permalink to “Relation with Item”">​</a></h2><p>With EmakiItem installed, Strengthen registers an item layer preview provider through <code>EmakiItemApi</code> from its conditionally loaded integration package, letting EmakiItem preview strengthen layer content. When EmakiItem is absent or disabled, that registration is skipped or released automatically without affecting strengthening.</p>`,22)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};